var create_expense_default = defineTool3({
  name: "create_expense",
  title: "Criar despesa",
  description: "Cria uma nova despesa para o usu\xE1rio autenticado. Requer descri\xE7\xE3o, valor, data (YYYY-MM-DD) e m\xE9todo de pagamento. Opcionalmente aceita category_id (UUID de user_categories).",
  inputSchema: {
    description: z3.string().trim().min(1).max(200),
    amount: z3.number().positive(),
    expense_date: z3.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    payment_method: z3.enum(["pix", "credit", "debit", "cash", "transfer"]),
    category_id: z3.string().uuid().optional()
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async (input, ctx) => {
    if (!ctx.isAuthenticated()) return mcpError("UNAUTHENTICATED");
    const supabase = supabaseForUser(ctx);
    let category_name = null;
    let category_icon = null;
    if (input.category_id) {
      const { data: cat } = await supabase.from("user_categories").select("name, icon").eq("id", input.category_id).eq("user_id", ctx.getUserId()).maybeSingle();
      if (cat) {
        category_name = cat.name;
        category_icon = cat.icon;
      }
    }
    const { data, error } = await supabase.from("expenses").insert({
      user_id: ctx.getUserId(),
      description: input.description,
      amount: input.amount,
      expense_date: input.expense_date,
      payment_method: input.payment_method,
      category: "outros",
      category_id: input.category_id ?? null,
      category_name,
      category_icon
    }).select().single();
    if (error) return mcpError("INTERNAL_ERROR", error.message);
    return {
      content: [{ type: "text", text: `Despesa criada: ${data.id}` }],
      structuredContent: { expense: data }
    };
  }
});

